using Mono.Cecil;using Mono.Cecil.Cil;using System.Security.Cryptography;using System.Text.Json;
const string Original="ea95a650360cd7f54c1905276afc3afa4829e2e4bf01d7ffb0b2900924c42cae";
string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
IEnumerable<TypeDefinition> All(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var a in All(n))yield return a;}
string Shape(MethodDefinition m){if(!m.HasBody)return "none";var instructions=m.Body.Instructions;string Operand(object v)=>v switch{Instruction i=>"@"+instructions.IndexOf(i),Instruction[] a=>string.Join(",",a.Select(i=>instructions.IndexOf(i))),_=>v?.ToString()??""};return string.Join("\n",instructions.Select(i=>i.OpCode.Name+":"+Operand(i.Operand)))+"/"+string.Join(",",m.Body.Variables.Select(v=>v.VariableType.FullName))+"/"+string.Join(",",m.Body.ExceptionHandlers.Select(e=>$"{e.HandlerType}:{instructions.IndexOf(e.TryStart)}:{instructions.IndexOf(e.TryEnd)}:{instructions.IndexOf(e.HandlerStart)}:{instructions.IndexOf(e.HandlerEnd)}"));}
string Metadata(AssemblyDefinition a)=>a.Name.FullName+"\n"+string.Join("\n",a.MainModule.AssemblyReferences.Select(x=>x.FullName))+"\n"+string.Join("\n",a.MainModule.Types.SelectMany(All).SelectMany(t=>new[]{t.FullName+":"+t.Attributes}.Concat(t.Fields.Select(f=>f.FullName+":"+f.Attributes)).Concat(t.CustomAttributes.Select(x=>x.AttributeType.FullName+":"+string.Join(",",x.ConstructorArguments.Select(p=>p.Value))))))+"\n"+string.Join("\n",a.MainModule.Resources.Select(r=>r.Name+":"+(r is EmbeddedResource e?Convert.ToHexString(SHA256.HashData(e.GetResourceData())):r.ResourceType.ToString())));
void Guard(string path,string input){path=Path.GetFullPath(path);if(path.Equals(Path.GetFullPath(input),StringComparison.OrdinalIgnoreCase)||File.Exists(path)||Directory.Exists(path)||File.Exists(path+".receipt.json"))throw new InvalidOperationException("New distinct output required");for(var p=new DirectoryInfo(Path.GetDirectoryName(path)!);p!=null;p=p.Parent){if(new[]{"BepInEx","UserData","mods","abdata"}.Contains(p.Name,StringComparer.OrdinalIgnoreCase)||p.Name.EndsWith("_Data",StringComparison.OrdinalIgnoreCase)||(new[]{".git"}.Any(x=>File.Exists(Path.Combine(p.FullName,x))||Directory.Exists(Path.Combine(p.FullName,x)))))throw new InvalidOperationException("Output outside repository/runtime/content required");if(File.Exists(Path.Combine(p.FullName,"CharaStudio.exe"))&&Path.GetRelativePath(p.FullName,path).Split(Path.DirectorySeparatorChar)[0]!=".scratch")throw new InvalidOperationException("Only private game scratch outputs allowed");}}
void Write(AssemblyDefinition a,string path){using var mem=new MemoryStream();a.Write(mem);Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);using var f=new FileStream(path,FileMode.CreateNew);mem.Position=0;mem.CopyTo(f);}
if(args.Length!=4||args[0]!="patch"&&args[0]!="probe")throw new ArgumentException("patch original game-root output | probe reviewed-input fixture output");
string mode=args[0],input=args[1],aux=args[2],output=args[3];Guard(output,input);string hash=Hash(input);if(mode=="patch"&&hash!=Original)throw new InvalidOperationException("Unknown exact input");
using var resolver=new DefaultAssemblyResolver();if(mode=="patch")foreach(var p in new[]{Path.Combine(aux,"BepInEx/core"),Path.Combine(aux,"BepInEx/plugins"),Path.Combine(aux,"CharaStudio_Data/Managed")}.Concat(Directory.GetDirectories(Path.Combine(aux,"BepInEx/plugins"),"*",SearchOption.AllDirectories)))resolver.AddSearchDirectory(p);
using var source=AssemblyDefinition.ReadAssembly(input,new ReaderParameters{AssemblyResolver=resolver});var module=source.MainModule;var owner=module.GetType("CoordinateLoadOption.MaterialEditor");
var callbacks=owner.NestedTypes.SelectMany(t=>t.Methods).Where(m=>m.Name=="<SetMaterialEditorData>b__1"||m.Name=="<RemoveMaterialEditorData>b__1").ToArray();if(callbacks.Length!=2)throw new InvalidOperationException("Unexpected callback count");
if(mode=="probe"){
 if(hash!=Original){using var receipt=JsonDocument.Parse(File.ReadAllText(input+".receipt.json"));if(receipt.RootElement.GetProperty("originalSha256").GetString()!=Original||receipt.RootElement.GetProperty("outputSha256").GetString()!=hash)throw new InvalidOperationException("Unreviewed probe input");}
 using var fixture=AssemblyDefinition.ReadAssembly(aux);var target=fixture.MainModule;var dest=target.GetType(owner.FullName);var closures=owner.NestedTypes.Where(t=>t.Name.Contains("DisplayClass30_")||t.Name.Contains("DisplayClass32_")).ToArray();
 foreach(var t in closures){var copy=new TypeDefinition(t.Namespace,t.Name,t.Attributes,Clone.TypeRef(t.BaseType,target));dest.NestedTypes.Add(copy);foreach(var f in t.Fields)copy.Fields.Add(new FieldDefinition(f.Name,f.Attributes,Clone.TypeRef(f.FieldType,target)));foreach(var m in t.Methods){var dm=new MethodDefinition(m.Name,m.Attributes,Clone.TypeRef(m.ReturnType,target));foreach(var p in m.Parameters)dm.Parameters.Add(new ParameterDefinition(p.Name,p.Attributes,Clone.TypeRef(p.ParameterType,target)));copy.Methods.Add(dm);}}
 foreach(var t in closures)foreach(var m in t.Methods.Where(x=>x.HasBody))Clone.Body(m,target.GetType(t.FullName).Methods.Single(x=>x.Name==m.Name),target);
 foreach(var m in owner.Methods.Where(m=>(m.Name=="SetMaterialEditorData"&&m.Parameters.Count==6)||(m.Name=="RemoveMaterialEditorData"&&m.Parameters.Count==4)))Clone.Body(m,dest.Methods.Single(x=>x.Name==m.Name),target);
 var forEach=module.GetType("Extension.Linq").Methods.Single(m=>m.Name=="ForEach");Clone.Body(forEach,target.GetType("Extension.Linq").Methods.Single(m=>m.Name=="ForEach"),target);Write(fixture,output);Console.WriteLine(JsonSerializer.Serialize(new{actualMethods=closures.Sum(t=>t.Methods.Count)+3,hash,externalCallsSynthetic=true}));return;
}
var methods=module.Types.SelectMany(All).SelectMany(t=>t.Methods).ToArray();var before=methods.ToDictionary(m=>m.MetadataToken.ToUInt32(),Shape);string metadata=Metadata(source);var counts=new List<object>();
foreach(var callback in callbacks){var il=callback.Body.GetILProcessor();var field=callback.DeclaringType.Fields.Single(f=>f.Name=="doFlag2");var stores=callback.Body.Instructions.Where(i=>i.OpCode==OpCodes.Stfld&&i.Operand is FieldReference f&&f.FullName==field.FullName).ToArray();if(stores.Length!=3||stores.Count(i=>i.Previous.OpCode==OpCodes.Ldc_I4_1)!=1||stores.Count(i=>i.Previous.OpCode==OpCodes.Ldc_I4_0)!=2)throw new InvalidOperationException("Unexpected flag writes");
 foreach(var store in stores){var value=store.Previous;var instance=value.Previous;if(instance.OpCode!=OpCodes.Ldarg_0)throw new InvalidOperationException("Unexpected flag stack");foreach(var i in new[]{instance,value,store}){i.OpCode=OpCodes.Nop;i.Operand=null;}}
 var invokes=callback.Body.Instructions.Where(i=>i.Operand is MethodReference m&&m.DeclaringType.FullName=="Extension.Reflection"&&m.Name=="Invoke").ToArray();if(invokes.Length==0)throw new InvalidOperationException("No target writes");foreach(var call in invokes){var pop=call.Next;if(pop.OpCode!=OpCodes.Pop)throw new InvalidOperationException("Unexpected Invoke return use");var load=il.Create(OpCodes.Ldarg_0);var yes=il.Create(OpCodes.Ldc_I4_1);var save=il.Create(OpCodes.Stfld,field);il.InsertAfter(pop,load);il.InsertAfter(load,yes);il.InsertAfter(yes,save);}
 foreach(var i in callback.Body.Instructions)i.OpCode=i.OpCode.Code switch{Code.Br_S=>OpCodes.Br,Code.Brtrue_S=>OpCodes.Brtrue,Code.Brfalse_S=>OpCodes.Brfalse,Code.Leave_S=>OpCodes.Leave,Code.Beq_S=>OpCodes.Beq,Code.Bne_Un_S=>OpCodes.Bne_Un,_=>i.OpCode};counts.Add(new{method=callback.FullName,returnedInvokeSites=invokes.Length});
}
var changedMethods=methods.Where(m=>before[m.MetadataToken.ToUInt32()]!=Shape(m)).ToArray();var changed=changedMethods.Select(m=>m.FullName).ToArray();var changedTokens=changedMethods.Select(m=>m.MetadataToken.ToUInt32()).ToArray();if(changed.Length!=2)throw new InvalidOperationException("Unexpected change scope");Write(source,output);
using(var written=AssemblyDefinition.ReadAssembly(output,new ReaderParameters{AssemblyResolver=resolver})){if(Metadata(written)!=metadata)throw new InvalidOperationException("Metadata changed");var after=written.MainModule.Types.SelectMany(All).SelectMany(t=>t.Methods).ToDictionary(m=>m.MetadataToken.ToUInt32(),Shape);if(after.Count!=before.Count||before.Where(x=>!changedTokens.Contains(x.Key)).Any(x=>after[x.Key]!=x.Value))throw new InvalidOperationException("Unrelated methods changed");}
var result=new{originalSha256=Original,outputSha256=Hash(output),changedMethods=changed,totalMethods=methods.Length,unchangedMethods=methods.Length-2,counts,identityAndResourcesPreserved=true,installed=false};File.WriteAllText(output+".receipt.json",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(result));
